## Code Example
```javascript
// useFeedLive.js (sketch)
import { useEffect, useState } from 'react'
import { fetchInitialFeed, subscribeToFeed, applyEvent } from './api'

export function useFeedLive() {
  const [feed, setFeed] = useState([])
  useEffect(() => {
    fetchInitialFeed().then(setFeed)
    const unsub = subscribeToFeed((ev) => {
      setFeed((f) => applyEvent(f, ev))
    })
    return unsub
  }, [])
  const like = (postId) => {
    setFeed((f) => f.map(p => p.id === postId ? { ...p, liked: true, likes: p.likes + 1 } : p))
    enqueueAction({ type: 'like', postId, ts: Date.now() })
  }
  return { feed, like }
}
```

